ing // OWNER, ADMIN, MANAGER, SALESPERSON, VIEWER\n  status       String   @default(\"ACTIVE\")\n  createdAt    DateTime @default(now())\n\n  assignedLeads Lead[]\n}\n\n// -------------------------------------\n// CRM: LEADS & CUSTOMERS\n// -------------------------------------\n\nmodel Customer {\n  id        String   @id @default(uuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id])\n  name      String\n  phone     String\n  email     String?\n  address   String?\n  source    String?\n  tags      String?\n  createdAt DateTime @default(now())\n\n  leads         Lead[]\n  conversations Conversation[]\n  quotations    Quotation[]\n}\n\nmodel Lead {\n  id           String    @id @default(uuid())\n  companyId    String\n  company      Company   @relation(fields: [companyId], references: [id])\n  customerId   String?\n  customer     Customer? @relation(fields: [customerId], references: [id])\n  assignedToId String?\n  assignedTo   User?     @relation(fields: [assignedToId], references: [id])\n\n  title      String? // e.g., \"Kitchen Renovation\"\n  status     String      @default(\"NEW\") // NEW, CONTACTED, QUALIFIED, QUOTATION, NEGOTIATION, WON, LOST\n  score      Int         @default(0) // 0-100\n  budget     Float?\n  source     String?\n  notes      String?\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n  quotations Quotation[]\n}\n\n// -------------------------------------\n// WHATSAPP INBOX\n// -------------------------------------\n\nmodel Conversation {\n  id            String   @id @default(uuid())\n  companyId     String\n  company       Company  @relation(fields: [companyId], references: [id])\n  customerId    String\n  customer      Customer @relation(fields: [customerId], references: [id])\n  status        String   @default(\"OPEN\") // OPEN, RESOLVED\n  lastMessageAt DateTime @default(now())\n  createdAt     DateTime @default(now())\n\n  messages Message[]\n}\n\nmodel Message {\n  id             String       @id @default(uuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id])\n  senderType     String // CUSTOMER, SALESPERSON, AI\n  senderId       String? // If SALESPERSON, points to User ID\n  content        String\n  messageType    String       @default(\"TEXT\") // TEXT, IMAGE, DOCUMENT\n  status         String       @default(\"SENT\") // SENT, DELIVERED, READ, FAILED\n  waMessageId    String?      @unique // ID from Meta\n  createdAt      DateTime     @default(now())\n}\n\n// -------------------------------------\n// QUOTATION SYSTEM\n// -------------------------------------\n\nmodel Quotation {\n  id         String   @id @default(uuid())\n  companyId  String\n  company    Company  @relation(fields: [companyId], references: [id])\n  customerId String\n  customer   Customer @relation(fields: [customerId], references: [id])\n  leadId     String?\n  lead       Lead?    @relation(fields: [leadId], references: [id])\n\n  subtotal   Float     @default(0)\n  discount   Float     @default(0)\n  total      Float     @default(0)\n  status     String    @default(\"DRAFT\") // DRAFT, SENT, VIEWED, ACCEPTED, REJECTED, EXPIRED\n  validUntil DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  items QuotationItem[]\n}\n\nmodel QuotationItem {\n  id          String    @id @default(uuid())\n  quotationId String\n  quotation   Quotation @relation(fields: [quotationId], references: [id], onDelete: Cascade)\n  description String\n  quantity    Int       @default(1)\n  unitPrice   Float\n  totalPrice  Float\n}\n",
